enum CreationError: Error { case missingCompulsory }

struct Contract {
    let customer: String      // compulsory, immutable after creation
    let supplier: String
    let startDate: Date

    init(customer: String, supplier: String, startDate: Date) throws {
        guard !customer.isEmpty, !supplier.isEmpty else {
            throw CreationError.missingCompulsory
        }
        self.customer = customer; self.supplier = supplier; self.startDate = startDate
    }
}
